#include <stdio.h>
#include <stdlib.h>

#define MAXN 200005

typedef long long ll;

int cmp_desc(const void *a, const void *b) {
    ll x = *(const ll *)a;
    ll y = *(const ll *)b;
    
    if(x < y) return 1;
    if (x > y) return -1;
    return 0;
}

ll get_value(
    int A,
    int q,
    int n,
    ll *pref
    ) {
    int r = 3 * n - (q + 3 * A) / 2;
    
    return 2LL* pref[A] + pref[q] + 3LL * pref[r];
}

int main() {
	int T;
	scanf("%d", &T);
	
	while (T--) {
	    int n;
	    scanf("%d", &n);
	    
	    int m = 3 * n;
	    
	    ll *a = malloc(sizeof(ll) * m);
	    
	    for (int i = 0; i < m; i++) {
	        scanf("%lld", &a[i]);
	    }
	    
	    qsort(a, m, sizeof(ll), cmp_desc);
	    
	    ll *pref = malloc(sizeof(ll) * (m+1));
	    
	    pref[0] = 0;
	    
	    for (int i = 0; i < m; i++) {
	        pref[i + 1] = pref[i] + a[i];
	    }
	    
	    ll ans = 0;
	    
	    for (int q = 0; q <= 2 * n; q++) {
            int lo = 0;
            int hi = q;
            
            if (hi > n) hi = n;
            
            if (hi > 2 * n - 1) hi = 2 * n - 1;
            
            if ((lo & 1) != (q & 1)) lo++;
            
            if ((hi & 1) != (q & 1)) hi--;
            
            if (lo > hi) continue;
            
            int left = lo;
            int right = hi;
            
            while (left < right) {
                int mid = left + ((right - left)/ 4) * 2;
                
                if (mid < left) mid = left;
                
                if (mid + 2 > hi) mid = hi - 2;
                
                if (mid < lo || mid + 2 > hi) break;
                
                ll v1 = get_value(mid, q, n, pref);
                ll v2 = get_value(mid + 2, q, n, pref);
                
                if (v2 >= v1) {
                    left = mid + 2;
                } else {
                    right = mid;
                }
            }
            
            for (int d = -4; d <= 4; d += 2) {
                int A = left + d;
                
                if (A < lo || A > hi) continue;
                
                ll cur = get_value(A, q, n, pref);
                
                if (cur > ans) {
                    ans = cur;
                }
            }
            
            ll vLo = get_value(lo, q, n, pref);
            ll vHi = get_value(hi, q, n, pref);
            
            if (vLo > ans) ans = vLo;
            if (vHi > ans) ans = vHi;
	    }
	    
	    printf("%lld\n", ans);
	    
	    free(a);
	    free(pref);
	    
 	}
 	
 	return 0;
}
